SELECT AVG(hourCnt) AS avgCnt, COUNT(*) AS samples
FROM (
    SELECT DATE_FORMAT(stat_hour, '%Y-%m-%d %H') AS h, SUM(cnt) AS hourCnt
    FROM ai_inspect_stat
    WHERE fp_id = #{fpId}
      AND HOUR(stat_hour) = #{hourOfDay}
      AND stat_hour >= #{sinceTime}
      AND stat_hour < #{excludeFrom}
    GROUP BY h
) t

SELECT stat_hour AS statHour, cnt AS cnt
FROM ai_inspect_stat
WHERE fp_id = #{fpId}
  AND stat_hour >= #{startTime}
  AND stat_hour <= #{endTime}
ORDER BY stat_hour ASC

SELECT COALESCE(SUM(cnt), 0)
FROM ai_inspect_stat
WHERE stat_hour >= #{startTime}
  AND stat_hour <= #{endTime}
  AND fp_id IN

    #{id}

SELECT fp_id AS fpId, SUM(cnt) AS cnt
FROM ai_inspect_stat
WHERE stat_hour >= #{startTime}
  AND stat_hour <= #{endTime}
  AND fp_id IN

    #{id}

GROUP BY fp_id

SELECT IFNULL(SUM(cnt), 0)
FROM ai_inspect_stat
WHERE fp_id = #{fpId}
  AND stat_hour >= #{startTime}
  AND stat_hour <= #{endTime}
